-- meta.ensure_partitions: Monthly partitions ahead of time (spec 03 section 8, FR-HRM-DAT-04; slice S1.11 Build item 5): for every monthly-partitioned table of the customer database (a parent with a <table>_default partition), creates <table>_pYYYY_MM for each month from p_first_month for p_months months when missing. Owned by the migration login and run with its rights, so the application login needs no right to create tables. A month whose rows already sit in the default partition is not created and is reported (outcome 'default_has_rows'), because attaching it would fail; an operator moves the rows first.
create or replace function meta.ensure_partitions(p_first_month date, p_months integer)
returns table (table_name text, partition_name text, outcome text)
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
declare
    parent record;
    month date;
    upper_month date;
    lower_bound text;
    upper_bound text;
    v_name text;
    has_rows boolean;
begin
    if p_months is null or p_months < 1 or p_months > 36 then
        raise exception 'ensure_partitions: months must be between 1 and 36' using errcode = '22023';
    end if;
    for parent in
        select n.nspname as schema_name, c.relname as rel_name, a.attname as key_column, format_type(a.atttypid, a.atttypmod) as key_type
        from pg_partitioned_table pt
        join pg_class c on c.oid = pt.partrelid
        join pg_namespace n on n.oid = c.relnamespace
        join pg_attribute a on a.attrelid = c.oid and a.attnum = pt.partattrs[0]
        where pt.partstrat = 'r' and pt.partnatts = 1
          and exists (select 1 from pg_inherits i join pg_class d on d.oid = i.inhrelid
                      where i.inhparent = c.oid and d.relname = c.relname || '_default')
        order by n.nspname, c.relname
    loop
        for i in 0 .. p_months - 1 loop
            month := (date_trunc('month', p_first_month) + make_interval(months => i))::date;
            upper_month := (month + interval '1 month')::date;
            v_name := parent.rel_name || '_p' || to_char(month, 'YYYY_MM');
            if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
                       where n.nspname = parent.schema_name and c.relname = v_name) then
                continue;
            end if;
            if parent.key_type = 'timestamp with time zone' then
                lower_bound := quote_literal(to_char(month, 'YYYY-MM-DD') || ' 00:00:00+00');
                upper_bound := quote_literal(to_char(upper_month, 'YYYY-MM-DD') || ' 00:00:00+00');
            else
                lower_bound := quote_literal(to_char(month, 'YYYY-MM-DD'));
                upper_bound := quote_literal(to_char(upper_month, 'YYYY-MM-DD'));
            end if;
            execute format('select exists (select 1 from %I.%I where %I >= %s and %I < %s)',
                parent.schema_name, parent.rel_name || '_default', parent.key_column, lower_bound, parent.key_column, upper_bound) into has_rows;
            if has_rows then
                table_name := parent.schema_name || '.' || parent.rel_name; partition_name := v_name; outcome := 'default_has_rows';
                return next;
                continue;
            end if;
            execute format('create table %I.%I partition of %I.%I for values from (%s) to (%s)',
                parent.schema_name, v_name, parent.schema_name, parent.rel_name, lower_bound, upper_bound);
            table_name := parent.schema_name || '.' || parent.rel_name; partition_name := v_name; outcome := 'created';
            return next;
        end loop;
    end loop;
end
$fn$;
revoke all on function meta.ensure_partitions(date, integer) from public;
grant execute on function meta.ensure_partitions(date, integer) to app_rw;
